import java.util.*;

class UndergroundSystem {
    private static final class Trip {
        final String station;
        final int time;
        Trip(String station, int time) {
            this.station = station;
            this.time = time;
        }
    }

    private static final class RouteKey {
        final String start;
        final String end;
        RouteKey(String start, String end) {
            this.start = start;
            this.end = end;
        }
        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof RouteKey)) {
                return false;
            }
            RouteKey that = (RouteKey) other;
            return start.equals(that.start) && end.equals(that.end);
        }
        @Override
        public int hashCode() {
            return Objects.hash(start, end);
        }
    }

    private static final class Stats {
        long total;
        int count;
        void add(int duration) {
            total += duration;
            count++;
        }
        double average() {
            return (double) total / count;
        }
    }

    private final Map<Integer, Trip> activeTrips = new HashMap<>();
    private final Map<RouteKey, Stats> completedRoutes = new HashMap<>();

    public UndergroundSystem() {
    }

    public void checkIn(int id, String stationName, int t) {
        activeTrips.put(id, new Trip(stationName, t));
    }

    public void checkOut(int id, String stationName, int t) {
        Trip trip = activeTrips.remove(id);
        RouteKey key = new RouteKey(trip.station, stationName);
        Stats stats = completedRoutes.computeIfAbsent(key, ignored -> new Stats());
        stats.add(t - trip.time);
    }

    public double getAverageTime(String startStation, String endStation) {
        return completedRoutes.get(new RouteKey(startStation, endStation)).average();
    }
}

