class UndergroundSystem {
    private static final class CheckIn {
        final String station;
        final int time;
        CheckIn(String station, int time) {
            this.station = station;
            this.time = time;
        }
    }

    private static final class Stats {
        long total;
        int count;
        void add(int duration) {
            total += duration;
            count++;
        }
    }

    private final Map<Integer, CheckIn> active = new HashMap<>();
    private final Map<String, Map<String, Stats>> routes = new HashMap<>();

    public UndergroundSystem() {
    }

    public void checkIn(int id, String stationName, int t) {
        active.put(id, new CheckIn(stationName, t));
    }

    public void checkOut(int id, String stationName, int t) {
        CheckIn start = active.remove(id);
        Map<String, Stats> byEnd = routes.computeIfAbsent(start.station, ignored -> new HashMap<>());
        Stats stats = byEnd.computeIfAbsent(stationName, ignored -> new Stats());
        stats.total += t - start.time;
        stats.count++;
