import java.util.*;

class UndergroundSystem {
    private final Map<String, Integer> stationIds = new HashMap<>();
    private final Map<Integer, int[]> active = new HashMap<>();
    private final Map<Long, long[]> routes = new HashMap<>();

    public UndergroundSystem() {
    }

    public void checkIn(int id, String stationName, int t) {
        int startId = stationId(stationName);
        active.put(id, new int[]{startId, t});
    }

    public void checkOut(int id, String stationName, int t) {
        int[] start = active.remove(id);
        int endId = stationId(stationName);
        long[] data = routes.computeIfAbsent(routeKey(start[0], endId), ignored -> new long[2]);
        data[0] += t - start[1];
        data[1]++;
    }

    public double getAverageTime(String startStation, String endStation) {
        int startId = stationId(startStation);
        int endId = stationId(endStation);
        long[] data = routes.get(routeKey(startId, endId));
        return (double) data[0] / data[1];
    }

    private int stationId(String stationName) {
        Integer existing = stationIds.get(stationName);
        if (existing != null) {
            return existing;
        }
        int created = stationIds.size() + 1;
        stationIds.put(stationName, created);
        return created;
    }

    private long routeKey(int startId, int endId) {
        return ((long) startId << 32) | (endId & 0xffffffffL);
    }
}

